{"command": "cd /workspace && python3 - <<'PY'
import subprocess, json, wave, numpy as np, struct
def call(name,args):
    return subprocess.run(['ft2','call',name,json.dumps(args)],capture_output=True,text=True,cwd='/workspace').stdout.strip()
insts={1:'kick',2:'snare',3:'tom',4:'hat',5:'openhat',6:'crash',7:'bass',8:'pad',9:'organ',10:'chip',11:'lead',12:'lead2'}
for i,nm in insts.items():
    p=f'src/wav/{nm}.wav'
    w=wave.open(p); src=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float); w.close()
    call('sample_save',{'path':f'/tmp/e{i}.wav','instrument':i,'sample':0,'format':'wav'})
    w=wave.open(f'/tmp/e{i}.wav'); n=w.getnframes(); wd=w.getsampwidth()
    y=np.frombuffer(w.readframes(n),dtype=('<i1' if wd==1 else '<i2')).astype(float); w.close()
    if wd==1: y=y*256.0   # scale 8bit to compare magnitude
    if len(y)==len(src):
        err=np.abs(y-src).max()/ (np.abs(src).max()+1)
        print(f'{i:2d} {nm:9s} frames match ({len(y)}) width={wd} relmaxerr={err:.3f}')
    else:
        print(f'{i:2d} {nm:9s} LEN MISMATCH src={len(src)} out={len(y)} width={wd}')
PY"}

